<div class="modal fade" id="modalVendedor" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><div class="modal-header"><h5 class="modal-title" id="tituloModalVendedor">Novo vendedor</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="acao" value="salvar"><input type="hidden" name="id" id="vendedor_id"><div class="mb-3"><label class="form-label">Nome <span class="text-danger">*</span></label><input class="form-control" name="nome" id="vendedor_nome" maxlength="60" required></div><label class="form-label">Ativo</label><select class="form-select" name="ativo" id="vendedor_ativo"><option value="1">Sim</option><option value="0">Não</option></select></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary"><i class="bi bi-check-lg me-1"></i>Salvar</button></div></form></div></div></div>